<section class="form-intro"><a class="back-link" href="/lancamentos">‹ Voltar para lançamentos</a><span class="eyebrow">Movimentação interna</span><h2 class="page-heading">Transferir entre contas</h2><p class="page-subtitle">O valor sai de uma conta e entra em outra sem alterar receitas ou despesas.</p></section>
<form method="post" action="/transferencias" class="form-card compact-form"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'] ?? '') ?>"><div class="transfer-visual"><span class="transfer-circle">↗</span><div><strong>Transferência interna</strong><small>Escolha origem e destino</small></div></div><div class="form-grid"><label class="field"><span>Conta de origem</span><select name="from_account_id" required><option value="">Selecione</option><?php foreach ($accounts as $account): ?><option value="<?= (int) $account->id ?>"><?= htmlspecialchars($account->name) ?> · R$ <?= number_format((float) $account->current_balance, 2, ',', '.') ?></option><?php endforeach; ?></select></label><label class="field"><span>Conta de destino</span><select name="to_account_id" required><option value="">Selecione</option><?php foreach ($accounts as $account): ?><option value="<?= (int) $account->id ?>"><?= htmlspecialchars($account->name) ?></option><?php endforeach; ?></select></label><label class="field"><span>Valor</span><div class="input-prefix"><b>R$</b><input type="number" name="amount" step="0.01" min="0.01" placeholder="0,00" required></div></label><label class="field"><span>Data</span><input type="date" name="transaction_date" value="<?= date('Y-m-d') ?>" required></label><label class="field field-wide"><span>Descrição</span><input type="text" name="description" value="Transferência entre contas" maxlength="180" required></label></div><div class="form-actions"><a href="/lancamentos" class="button button-ghost">Cancelar</a><button class="button button-primary" type="submit">Confirmar transferência</button></div></form>
